-    return select(x,feasible_old,candidate_value > old_value);
+    let d = x - feasible_old;
+    let gradient = cdot + native_mul_mv(k, feasible_old - old);
+    let objective_change = dot(d, gradient) + 0.5 * dot(d, native_mul_mv(k,d));
+    // Compare the change directly to avoid cancellation between total objectives.
+    return select(x,feasible_old,objective_change > 0.0);
 }

